with filtered as (select *, datediff(current_date(), hire_date) as days_since_hire_date, floor(salary) as salary_whole from employees where hire_date >= to_date('2023-03-23')) select *, sum(days_since_hire_date) over (partition by level, manager_id order by days_since_hire_date, id rows between unbounded preceding and current row) as running_days_since_hire_date, last_value(days_since_hire_date, true) over (partition by level, job_title order by salary, id rows between unbounded preceding and current row) as last_known_days_since_hire_date, avg(salary) over (order by salary, id rows between 5 preceding and 1 preceding) as salary_avg_5_prior, first_value(job_title) ignore nulls over (partition by date_trunc('week', hire_date), dept_id order by days_since_hire_date, id rows between unbounded preceding and current row) as first_known_job_title, sum(salary) over w_recent as cumulative_salary from filtered window w_recent as (order by salary_whole, id rows between unbounded preceding and current row)
